import re, pathlib
root = pathlib.Path('.')
files = ['00-index.md','01-product-and-architecture.md','02-installation-and-platforms.md','03-rootless-and-userns.md']
TOK = re.compile(r'`((?:pages|samples)/[^`\s:]+):(\d+)(?:-(\d+))?`')
for f in files:
    txt = (root/f).read_text()
    lines = txt.splitlines()
    heads = [l for l in lines if l.startswith('## ')]
    print(f'{f}: lines={len(lines)} first={lines[0]!r} last2={heads[-2:]}')
    for p,a,b in TOK.findall(txt):
        fp = root/p
        if not fp.is_file():
            print('  MISSING', p); continue
        n = len(fp.read_text().splitlines())
        lo,hi = int(a), int(b or a)
        if lo<1 or hi<lo or hi>n:
            print('  OUT OF RANGE', f, p, a, b, 'n=',n)
    for bad in ('TBD','TODO','PLACEHOLDER','unverified claim'):
        if bad in txt: print('  PLACEHOLDER', f, bad)
    i=0
    while i < len(lines):
        if lines[i].startswith('```'):
            lang=lines[i][3:].strip(); head=lines[i-1] if i else ''
            j=i+1; body=[]
            while j<len(lines) and not lines[j].startswith('```'):
                body.append(lines[j]); j+=1
            toks=TOK.findall(head)
            if not lang: print('  FENCE NO LANG',f,i+1)
            if len(toks)>1: print('  FENCE MULTI TOK',f,i+1)
            if toks:
                p,a,b=toks[0]; src=(root/p).read_text().splitlines()
                lo,hi=int(a),int(b or a)
                want=[l.rstrip() for l in src[lo-1:hi] if l.strip()!='…']
                got=[l.rstrip() for l in body if l.strip()!='…']
                if want!=got:
                    print('  FENCE MISMATCH',f,i+1,p,a,b)
                    for k,(w,g) in enumerate(zip(want,got)):
                        if w!=g: print('    line',k,'want',repr(w),'got',repr(g))
                    if len(want)!=len(got): print('    len',len(want),len(got))
            if len(body)>25: print('  FENCE TOO LONG',f,i+1,len(body))
            i=j+1
        else: i+=1
PY)
